-- Auth lifecycle and initial catalog. Safe to re-run.
create or replace function private.handle_new_user() returns trigger language plpgsql security definer set search_path = '' as $$
begin
 insert into public.profiles(id,display_name,avatar_url)
 values(new.id,nullif(new.raw_user_meta_data->>'full_name',''),nullif(new.raw_user_meta_data->>'avatar_url',''))
 on conflict(id) do nothing;
 return new;
end; $$;
revoke all on function private.handle_new_user() from public,anon,authenticated;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute function private.handle_new_user();
insert into public.profiles(id,display_name,avatar_url)
select id,nullif(raw_user_meta_data->>'full_name',''),nullif(raw_user_meta_data->>'avatar_url','') from auth.users on conflict(id) do nothing;
